using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Runtime.CompilerServices;
using Interpreter.Core.Cascade;

namespace Interpreter.Tests.Live;

/// <summary>
/// Synthetic test speech for live provider checks (docs/GUARDRAILS.md: synthetic data only). Speech is
/// generated by OpenAI TTS from fixed, invented sentences; nothing is recorded from a person.
/// </summary>
internal static class SyntheticSpeech
{
    public static string? Env(string name) => Environment.GetEnvironmentVariable(name) is { Length: > 0 } v ? v : null;

    /// <summary>24 kHz mono PCM16 of the sentence.</summary>
    public static async Task<byte[]> Pcm24Async(string text, CancellationToken ct)
    {
        using var http = new HttpClient { Timeout = TimeSpan.FromSeconds(30) };
        using var req = new HttpRequestMessage(HttpMethod.Post, "https://api.openai.com/v1/audio/speech")
        {
            Content = JsonContent.Create(new { model = "gpt-4o-mini-tts", voice = "alloy", input = text, response_format = "pcm" }),
        };
        req.Headers.Authorization = new AuthenticationHeaderValue("Bearer", Env("OPENAI_API_KEY"));
        using var res = await http.SendAsync(req, ct);
        res.EnsureSuccessStatusCode();
        return await res.Content.ReadAsByteArrayAsync(ct);
    }

    /// <summary>Streams audio in 20 ms frames at about real time, then a second of silence so endpointing fires.</summary>
    public static async IAsyncEnumerable<AudioFrame> Frames(byte[] pcm, int rate, [EnumeratorCancellation] CancellationToken ct)
    {
        var frameBytes = rate / 50 * 2;
        var padded = pcm.Concat(new byte[rate * 2 * 3 / 2]).ToArray();
        for (var i = 0; i < padded.Length; i += frameBytes)
        {
            yield return new AudioFrame(padded.AsMemory(i, Math.Min(frameBytes, padded.Length - i)), rate);
            await Task.Delay(10, ct); // faster than real time is fine for both providers; keep it gentle
        }
    }
}
